def compute(vars):
    values = [vars["v1"], vars["v2"]]
    count = sum(1 for value in values if value > 3000)
    return {
        "value": count,
        "trace": {
            "values": values,
            "threshold": 3000,
            "years_exceeding_threshold": count,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "years"
            }
        }
    }
